#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Non-secret facts only. Secrets go to your password manager, never here.
# Kept under the workspace, not $HOME: the dev container is rebuilt and loses ~/.
# Override with SMH_FACTS_FILE=... if the workspace lives elsewhere.
ENV_FILE="${SMH_FACTS_FILE:-/workspaces/audiobook-ai-docker-image/myProjects/skillWizardRun/smh-platform-facts.env}"
mkdir -p "$(dirname "$ENV_FILE")"
TOTAL_STAGES=13

banner "Meta (Facebook + Instagram) setup for Social Media Harvester"

stage "Ground rule: where secrets go"
warn "This wizard NEVER asks for a secret. Do not paste one into it."
say "Secrets (App secret, System User token) go ONLY into your password manager."
say "Non-secret facts (ids, names, statuses, test results) are saved to:"
note "  $ENV_FILE"
note "Meta's UI changes often: if a menu differs, look for the named item nearby."
pause "Password manager open and ready?"

stage "Business portfolio"
open_url "https://business.facebook.com/settings/info"
step "If you have no business portfolio, create one with your business's legal name."
step "Business settings → Business info: copy the Business portfolio ID."
ask META_BUSINESS_ID "Business portfolio ID:"
write_env META_BUSINESS_ID "$META_BUSINESS_ID"

stage "Facebook Page in the portfolio"
open_url "https://business.facebook.com/settings/pages"
step "Accounts → Pages → Add → add your existing Page (you must be its admin)."
ask FB_PAGE_NAME "Page name:"
write_env FB_PAGE_NAME "$FB_PAGE_NAME"
ask FB_PAGE_ID "Page ID (Page → About → Page transparency, or the Pages list):"
write_env FB_PAGE_ID "$FB_PAGE_ID"

stage "Instagram Business account: link to Page + portfolio"
step "In the Instagram app: Settings → Account type and tools → confirm 'Business'."
step "Link it to the Page: Page settings → Linked accounts → Instagram → Connect."
open_url "https://business.facebook.com/settings/instagram-account-v2s"
step "Business settings → Accounts → Instagram accounts → Add → your account."
ask IG_USERNAME "Instagram @username:"
write_env IG_USERNAME "$IG_USERNAME"
ask IG_ACCOUNT_TYPE "Account type (Business or Creator):"
write_env IG_ACCOUNT_TYPE "$IG_ACCOUNT_TYPE"
note "This one account is both the Business Discovery querying account and a test Authorized Handle."

stage "Start Business Verification"
open_url "https://business.facebook.com/settings/security"
step "Security Center → Business verification → Start verification."
step "Have ready: legal name + address, a registration document or utility bill,"
step "and a business phone, email domain or website to confirm."
note "It can take days. It gates Page Public Content Access and Advanced Access."
ask META_BV_STATUS "Status (e.g. submitted / in review / verified / blocked: why):"
write_env META_BV_STATUS "$META_BV_STATUS"

stage "Create the Meta developer app"
open_url "https://developers.facebook.com/apps/creation/"
step "Name 'Social Media Harvester', contact email = yours."
step "Use case: choose 'Other' (if shown) → app type 'Business'."
step "Connect it to your business portfolio. Create."
step "Copy the App ID from the dashboard top bar (not secret)."
ask META_APP_ID "App ID:"
write_env META_APP_ID "$META_APP_ID"

stage "App settings → Basic"
open_url "https://developers.facebook.com/apps/$META_APP_ID/settings/basic/"
step "App secret → Show → save it to your password manager. Not here."
pause "App secret saved in password manager?"
step "Fill in: Privacy policy URL, App icon (1024x1024), Category. Save changes."
note "App Review needs these. If you have no privacy policy URL yet, note it."
ask META_APP_BASICS "Basics filled? (e.g. 'all done' / 'no privacy URL yet'):"
write_env META_APP_BASICS "$META_APP_BASICS"

stage "Facebook Login for Business configuration"
open_url "https://developers.facebook.com/apps/$META_APP_ID/dashboard/"
step "Add product / use case 'Facebook Login for Business'."
step "Settings → Valid OAuth Redirect URIs → add:"
note "  http://localhost:8080/login/oauth2/code/facebook"
step "Configurations → Create configuration → token type 'User access token' →"
step "permissions: pages_show_list, pages_read_engagement, read_insights,"
step "instagram_basic, instagram_manage_insights (add business_management if offered)."
ask META_FLB_CONFIG_ID "Configuration ID (not secret):"
write_env META_FLB_CONFIG_ID "$META_FLB_CONFIG_ID"

stage "Instagram product (via Facebook Login)"
open_url "https://developers.facebook.com/apps/$META_APP_ID/dashboard/"
step "Add product / use case 'Instagram' → choose 'API setup with Facebook login'."
warn "NOT 'Instagram Login': that path can't run Business Discovery."
pause "Instagram product added?"

stage "System User + never-expiring token"
open_url "https://business.facebook.com/settings/system-users"
step "Add → name 'smh-system' → role Admin → Create."
step "Assign assets: the app (full control), the Page, the Instagram account."
step "Generate new token → app 'Social Media Harvester' → expiration 'Never' →"
step "permissions: pages_show_list, pages_read_engagement, read_insights,"
step "instagram_basic, instagram_manage_insights, business_management → Generate."
warn "Save the token to your password manager NOW. Do NOT paste it here."
pause "Token saved in password manager?"
ask META_SYSTEM_USER_ID "System User ID (shown on its row; not secret):"
write_env META_SYSTEM_USER_ID "$META_SYSTEM_USER_ID"

stage "Request Page Public Content Access"
open_url "https://developers.facebook.com/apps/$META_APP_ID/app-review/permissions/"
step "Search 'Page Public Content Access' → Request advanced access."
step "Note what it requires (Business Verification, screencast, use-case text...)."
ask META_PPCA_STATUS "Status / blockers (e.g. 'needs BV first'):"
write_env META_PPCA_STATUS "$META_PPCA_STATUS"

stage "Smoke test: your Page + Instagram via Graph API Explorer"
open_url "https://developers.facebook.com/tools/explorer/"
step "Meta App: 'Social Media Harvester'. User or Page: 'Get User Access Token'."
step "Add the 5 permissions above → Generate Access Token → approve your Page + IG."
step "GET (v27.0):"
note "  me/accounts?fields=name,id,instagram_business_account"
step "Copy instagram_business_account.id from the result (not secret)."
ask IG_BUSINESS_ACCOUNT_ID "Instagram business account ID:"
write_env IG_BUSINESS_ACCOUNT_ID "$IG_BUSINESS_ACCOUNT_ID"
ask META_SMOKE_ACCOUNTS "Result (e.g. 'ok page + ig returned' or the error):"
write_env META_SMOKE_ACCOUNTS "$META_SMOKE_ACCOUNTS"

stage "Smoke test: Business Discovery + PPCA probe (System User token)"
step "In the Explorer, paste the System User token from your password manager"
step "into the Access Token field (browser only). GET:"
note "  $IG_BUSINESS_ACCOUNT_ID?fields=business_discovery.username(nba){followers_count,media_count}"
ask META_SMOKE_BUSINESS_DISCOVERY "Result (e.g. 'ok followers=...' or the error):"
write_env META_SMOKE_BUSINESS_DISCOVERY "$META_SMOKE_BUSINESS_DISCOVERY"
step "Optional PPCA probe, same token. GET:"
note "  nba/posts?limit=1"
ask META_SMOKE_PPCA_PROBE "Result or error text (Enter 'skipped' to skip):"
write_env META_SMOKE_PPCA_PROBE "$META_SMOKE_PPCA_PROBE"
warn "Clear the token from the Explorer when done."

finish
note "Tell Claude you're done; it will read $ENV_FILE (no secrets in it)."
}

run_wizard "$@"; exit
